  }
}
"
    }
  ],
  "registeredSlots": [
    "todo.header.actions",
    "todo.item.badges",
    "todo.item.detail",
    "todo.list.banner",
    "todo.sidebar.sections"
  ],
  "registeredEvents": [
    "todo:before-transition",
    "todo:changed"
