", "sourceFiles": {"server.ts": "import { Service, type Context } from "cordis";
import type { ScopedDb } from "@host/server-sdk";
import type {
  CreateTagInput,
  Tag,
  TagColor,
  TagService,
} from "./contract.d.ts";

const TAG_COLORS: readonly TagColor[] = [
  "slate",
  "blue",
  "green",
  "amber",
  "rose",
  "violet",
];

const DEFAULT_TAG_COLOR: TagColor = "slate";
const MAX_TAG_NAME_LENGTH = 32;

const TAG_COLUMNS = "id, name, color, created_at";

interface TagRow {
  readonly id: string;
  readonly name: string;
  readonly color: string;
  readonly created_at: string;
}

function isTagColor(value: unknown): value is TagColor {
  return (
    typeof value === "string" && (TAG_COLORS as readonly string[]).includes(value)
  );
}

function toTag(row: TagRow): Tag {
  return {
    id: row.id,
    name: row.name,
    color: isTagColor(row.color) ? row.color : DEFAULT_TAG_COLOR,
    createdAt: row.created_at,
  };
}

function normalizeTagName(raw: string): string {
  return raw.trim().replace(/\s+/g, " ");
}

function httpError(status: number, message: string): Error & { status: number } {
  const error = new Error(message) as Error & { status: number };
  error.status = status;
  return error;
}

export default class TodoTagsService extends Service implements TagService {
  private readonly db: ScopedDb;

  constructor(ctx: Context) {
    super(ctx, "tags");
    this.db = ctx.db;

    this.db.exec(`
      CREATE TABLE IF NOT EXISTS plg_todo_tags__tags (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        name_key TEXT NOT NULL UNIQUE,
        color TEXT NOT NULL DEFAULT 'slate',
        created_at TEXT NOT NULL
      )
    `);
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS plg_todo_tags__task_tags (
        task_id TEXT NOT NULL,
        tag_id TEXT NOT NULL,
        created_at TEXT NOT NULL,
        PRIMARY KEY (task_id, tag_id)
      )
    `);
    this.db.exec(
      "CREATE INDEX IF NOT EXISTS plg_todo_tags__task_tags_by_task ON plg_todo_tags__task_tags (task_id)",
    );

    ctx.http.route("GET", "/tags", () => ({ tags: this.list() }));

    ctx.http.route("POST", "/tags", (req) => {
      const body = (req.body ?? {}) as { name?: unknown; color?: unknown };
      if (typeof body.name !== "string") {
        return { status: 400, body: { error: "Tag name is required" } };
      }
      if (body.color !== undefined && !isTagColor(body.color)) {
        return {
          status: 400,
          body: { error: `Invalid tag color: ${String(body.color)}` },
        };
      }
      const name = normalizeTagName(body.name);
      if (!name) {
        return { status: 400, body: { error: "Tag name is required" } };
      }
      if (name.length > MAX_TAG_NAME_LENGTH) {
        return {
          status: 400,
          body: {
            error: `Tag name must be at most ${MAX_TAG_NAME_LENGTH} characters`,
          },
        };
      }
      if (this.findByName(name)) {
        return { status: 409, body: { error: `Tag already exists: ${name}` } };
      }
      return { status: 201, body: { tag: this.create({ name, color: body.color }) } };
    });

    ctx.http.route("DELETE", "/tags/:id", (req) => {
      if (!this.delete(req.params.id)) {
        return { status: 404, body: { error: "Tag not found" } };
      }
      return { deleted: true, id: req.params.id };
    });

    ctx.http.route("GET", "/tasks/:taskId/tags", (req) => ({
      taskId: req.params.taskId,
      tags: this.listForTask(req.params.taskId),
    }));

    ctx.http.route("POST", "/tasks/:taskId/tags", (req) => {
      const body = (req.body ?? {}) as { tagId?: unknown };
      if (typeof body.tagId !== "string" || body.tagId.length === 0) {
        return { status: 400, body: { error: "tagId is required" } };
      }
      if (!this.get(body.tagId)) {
        return { status: 404, body: { error: "Tag not found" } };
      }
      return { tags: this.attach(req.params.taskId, body.tagId) };
    });

    ctx.http.route("PUT", "/tasks/:taskId/tags", (req) => {
      const body = (req.body ?? {}) as { tagIds?: unknown };
      if (
        !Array.isArray(body.tagIds) ||
        body.tagIds.some((value) => typeof value !== "string")
      ) {
        return {
          status: 400,
          body: { error: "tagIds must be an array of tag ids" },
        };
      }
      const tagIds = Array.from(new Set(body.tagIds as string[]));
      const unknownIds = tagIds.filter((id) => !this.get(id));
      if (unknownIds.length > 0) {
        return {
          status: 400,
          body: { error: `Unknown tag ids: ${unknownIds.join(", ")}` },
        };
      }
      return { tags: this.setForTask(req.params.taskId, tagIds) };
    });

    ctx.http.route("DELETE", "/tasks/:taskId/tags/:tagId", (req) => ({
      tags: this.detach(req.params.taskId, req.params.tagId),
    }));
  }

  list(): Tag[] {
    const rows = this.db
      .prepare(
        `SELECT ${TAG_COLUMNS} FROM plg_todo_tags__tags ORDER BY name_key ASC`,
      )
      .all<TagRow>();
    return rows.map(toTag);
  }

  get(id: string): Tag | null {
    const row = this.db
      .prepare(`SELECT ${TAG_COLUMNS} FROM plg_todo_tags__tags WHERE id = ?`)
      .get<TagRow>(id);
    return row ? toTag(row) : null;
  }

  create(input: string | CreateTagInput): Tag {
    const rawName = typeof input === "string" ? input : input.name;
    const name = normalizeTagName(rawName ?? "");
    if (!name) {
      throw httpError(400, "Tag name is required");
    }
    if (name.length > MAX_TAG_NAME_LENGTH) {
      throw httpError(
        400,
        `Tag name must be at most ${MAX_TAG_NAME_LENGTH} characters`,
      );
    }
    const color =
      typeof input === "string" ? DEFAULT_TAG_COLOR : (input.color ?? DEFAULT_TAG_COLOR);
    if (!isTagColor(color)) {
      throw httpError(400, `Invalid tag color: ${String(color)}`);
    }
    if (this.findByName(name)) {
      throw httpError(409, `Tag already exists: ${name}`);
    }

    const now = new Date().toISOString();
    const id = globalThis.crypto.randomUUID();
    this.db
      .prepare(
        "INSERT INTO plg_todo_tags__tags (id, name, name_key, color, created_at) VALUES (?, ?, ?, ?, ?)",
      )
      .run(id, name, name.toLowerCase(), color, now);

    this.emitChanged(null, [id]);
    return this.get(id)!;
  }

  delete(id: string): boolean {
    if (!this.get(id)) return false;

    this.db
      .prepare("DELETE FROM plg_todo_tags__task_tags WHERE tag_id = ?")
      .run(id);
    const result = this.db
      .prepare("DELETE FROM plg_todo_tags__tags WHERE id = ?")
      .run(id);
    const deleted = Number(result.changes) > 0;
    if (deleted) {
      this.emitChanged(null, [id]);
    }
    return deleted;
  }

  listForTask(taskId: string): Tag[] {
    const rows = this.db
      .prepare(
        `SELECT t.id, t.name, t.color, t.created_at
           FROM plg_todo_tags__task_tags AS tt
           JOIN plg_todo_tags__tags AS t ON t.id = tt.tag_id
          WHERE tt.task_id = ?
          ORDER BY t.name_key ASC`,
      )
      .all<TagRow>(taskId);
    return rows.map(toTag);
  }

  attach(taskId: string, tagId: string): Tag[] {
    if (!this.get(tagId)) {
      throw httpError(404, "Tag not found");
    }
    const alreadyAttached = this.listForTask(taskId).some(
      (tag) => tag.id === tagId,
    );
    if (!alreadyAttached) {
      this.db
        .prepare(
          "INSERT OR IGNORE INTO plg_todo_tags__task_tags (task_id, tag_id, created_at) VALUES (?, ?, ?)",
        )
        .run(taskId, tagId, new Date().toISOString());
      this.emitChanged(taskId, this.listForTask(taskId).map((tag) => tag.id));
    }
    return this.listForTask(taskId);
  }

  detach(taskId: string, tagId: string): Tag[] {
    this.db
      .prepare(
        "DELETE FROM plg_todo_tags__task_tags WHERE task_id = ? AND tag_id = ?",
      )
      .run(taskId, tagId);
    const tags = this.listForTask(taskId);
    this.emitChanged(taskId, tags.map((tag) => tag.id));
    return tags;
  }

  setForTask(taskId: string, tagIds: readonly string[]): Tag[] {
    const unique = Array.from(new Set(tagIds));
    for (const tagId of unique) {
      if (!this.get(tagId)) {
        throw httpError(400, `Unknown tag id: ${tagId}`);
      }
    }

    this.db
      .prepare("DELETE FROM plg_todo_tags__task_tags WHERE task_id = ?")
      .run(taskId);
    const now = new Date().toISOString();
    for (const tagId of unique) {
      this.db
        .prepare(
          "INSERT OR IGNORE INTO plg_todo_tags__task_tags (task_id, tag_id, created_at) VALUES (?, ?, ?)",
        )
        .run(taskId, tagId, now);
    }

    const tags = this.listForTask(taskId);
    this.emitChanged(taskId, tags.map((tag) => tag.id));
    return tags;
  }

  private findByName(name: string): Tag | null {
    const row = this.db
      .prepare(
        `SELECT ${TAG_COLUMNS} FROM plg_todo_tags__tags WHERE name_key = ?`,
      )
      .get<TagRow>(name.toLowerCase());
    return row ? toTag(row) : null;
  }

  private emitChanged(taskId: string | null, tagIds: readonly string[]): void {
    this.ctx.emit("tags:changed", { taskId, tagIds });
  }
}
", "client.tsx": "import {
  useCallback,
  useEffect,
  useState,
  type ComponentType,
} from "react";
import type { Context } from "cordis";
import { Check, Plus, Tag as TagIcon } from "lucide-react";
import type { Tag, TagColor, TagSlotProps } from "./contract.d.ts";

const TAGS_CHANGED_EVENT = "todo-tags:changed";

const TAG_COLORS: readonly TagColor[] = [
  "slate",
  "blue",
  "green",
  "amber",
  "rose",
  "violet",
];

const TAG_COLOR_HEX: Record<TagColor, string> = {
  slate: "#64748b",
  blue: "#2563eb",
  green: "#15803d",
  amber: "#b45309",
  rose: "#be123c",
  violet: "#7c3aed",
};

const TAG_COLOR_LABELS: Record<TagColor, string> = {
  slate: "灰",
  blue: "蓝",
  green: "绿",
  amber: "琥珀",
  rose: "玫红",
  violet: "紫",
};

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function chipStyle(color: TagColor) {
  const hex = TAG_COLOR_HEX[color] ?? TAG_COLOR_HEX.slate;
  return {
    color: hex,
    borderColor: `${hex}66`,
    backgroundColor: `${hex}14`,
  };
}

function tagsChanged(): void {
  window.dispatchEvent(new Event(TAGS_CHANGED_EVENT));
}

const TASK_TAGS_URL = (taskId: string) =>
  `/api/app/todo-tags/tasks/${encodeURIComponent(taskId)}/tags`;

/** Read-only chips rendered inline in every task row. */
export function TaskTagBadges({ task }: TagSlotProps) {
  const [tags, setTags] = useState<readonly Tag[]>([]);

  const load = useCallback(async () => {
    try {
      const data = await requestJson<{ tags: Tag[] }>(TASK_TAGS_URL(task.id));
      setTags(Array.isArray(data.tags) ? data.tags : []);
    } catch {
      setTags([]);
    }
  }, [task.id]);

  useEffect(() => {
    void load();
  }, [load]);

  useEffect(() => {
    const handleChanged = () => {
      void load();
    };
    window.addEventListener(TAGS_CHANGED_EVENT, handleChanged);
    return () => window.removeEventListener(TAGS_CHANGED_EVENT, handleChanged);
  }, [load]);

  if (tags.length === 0) return null;

  return (
    <span
      data-todo-tags-badges={task.id}
      className="flex flex-wrap items-center gap-1"
    >
      {tags.map((tag) => (
        <span
          key={tag.id}
          data-todo-tag-badge={tag.id}
          title={`标签：${tag.name}`}
          style={chipStyle(tag.color)}
          className="inline-flex max-w-[9rem] items-center rounded-full border px-2 py-0.5 text-[11px] leading-5 font-medium"
        >
          <span className="truncate">{tag.name}</span>
        </span>
      ))}
    </span>
  );
}

/** Tag picker + inline tag creation, rendered inside the task detail panel. */
export function TaskTagEditor({ task }: TagSlotProps) {
  const [allTags, setAllTags] = useState<readonly Tag[]>([]);
  const [selectedIds, setSelectedIds] = useState<readonly string[]>([]);
  const [draft, setDraft] = useState("");
  const [draftColor, setDraftColor] = useState<TagColor>("blue");
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    try {
      const [catalog, assigned] = await Promise.all([
        requestJson<{ tags: Tag[] }>("/api/app/todo-tags/tags"),
        requestJson<{ tags: Tag[] }>(TASK_TAGS_URL(task.id)),
      ]);
      setAllTags(Array.isArray(catalog.tags) ? catalog.tags : []);
      setSelectedIds(
        Array.isArray(assigned.tags) ? assigned.tags.map((tag) => tag.id) : [],
      );
      setError("");
    } catch (err) {
      setError(errorMessage(err));
    } finally {
      setLoading(false);
    }
  }, [task.id]);

  useEffect(() => {
    setLoading(true);
    void load();
  }, [load]);

  const replaceSelection = useCallback(
    async (tagIds: readonly string[]) => {
      setBusy(true);
      try {
        const data = await requestJson<{ tags: Tag[] }>(TASK_TAGS_URL(task.id), {
          method: "PUT",
          body: JSON.stringify({ tagIds }),
        });
        setSelectedIds(
          Array.isArray(data.tags) ? data.tags.map((tag) => tag.id) : [],
        );
        setError("");
        tagsChanged();
      } catch (err) {
        setError(errorMessage(err));
      } finally {
        setBusy(false);
      }
    },
    [task.id],
  );

  const toggleTag = (tagId: string) => {
    if (busy) return;
    const next = selectedIds.includes(tagId)
      ? selectedIds.filter((id) => id !== tagId)
      : [...selectedIds, tagId];
    void replaceSelection(next);
  };

  const createTag = async () => {
    const name = draft.trim();
    if (!name || busy) return;
    setBusy(true);
    setError("");
    try {
      const created = await requestJson<{ tag: Tag }>(
        "/api/app/todo-tags/tags",
        {
          method: "POST",
          body: JSON.stringify({ name, color: draftColor }),
        },
      );
      const newTagId = created.tag?.id;
      if (newTagId) {
        await requestJson<{ tags: Tag[] }>(TASK_TAGS_URL(task.id), {
          method: "PUT",
          body: JSON.stringify({ tagIds: [...selectedIds, newTagId] }),
        });
      }
      setDraft("");
      await load();
      tagsChanged();
    } catch (err) {
      setError(errorMessage(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <section data-todo-tag-editor={task.id} className="space-y-2">
      <div className="flex items-center justify-between gap-2">
        <h3 className="flex items-center gap-1.5 text-xs font-medium text-muted">
          <TagIcon className="size-3.5" aria-hidden="true" />
          <span>标签</span>
        </h3>
        <span className="text-[11px] tabular-nums text-muted">
          已选 {selectedIds.length}
        </span>
      </div>

      {loading ? (
        <p className="text-xs text-muted">正在加载标签…</p>
      ) : allTags.length === 0 ? (
        <p className="text-xs text-muted">还没有标签，先创建一个。</p>
      ) : (
        <div className="flex flex-wrap gap-1.5">
          {allTags.map((tag) => {
            const active = selectedIds.includes(tag.id);
            return (
              <button
                key={tag.id}
                type="button"
                disabled={busy}
                aria-pressed={active}
                data-todo-tag-toggle={tag.id}
                data-todo-tag-active={active ? "true" : "false"}
                onClick={() => toggleTag(tag.id)}
                style={active ? chipStyle(tag.color) : undefined}
                className={`inline-flex min-h-9 max-w-[10rem] items-center gap-1 rounded-full border px-2.5 py-1 text-[11px] font-medium transition-colors disabled:opacity-45 ${
                  active
                    ? "border-transparent"
                    : "border-line bg-surface text-muted hover:border-accent/40 hover:text-ink"
                }`}
              >
                {active && <Check className="size-3" aria-hidden="true" />}
                <span className="truncate">{tag.name}</span>
              </button>
            );
          })}
        </div>
      )}

      {/* No nested <form>: this slot renders inside the task detail form. */}
      <div className="flex items-center gap-1.5">
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault();
              void createTag();
            }
          }}
          placeholder="新标签名称"
          aria-label="新标签名称"
          data-todo-tag-create-input="true"
          className="min-h-9 min-w-0 flex-1 rounded-md border border-line bg-surface px-2.5 py-1.5 text-xs text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
        />
        <select
          value={draftColor}
          onChange={(event) => setDraftColor(event.target.value as TagColor)}
          aria-label="标签颜色"
          data-todo-tag-color-select="true"
          className="min-h-9 rounded-md border border-line bg-surface px-1.5 py-1.5 text-xs text-ink outline-none focus:border-accent"
        >
          {TAG_COLORS.map((color) => (
            <option key={color} value={color}>
              {TAG_COLOR_LABELS[color]}
            </option>
          ))}
        </select>
        <button
          type="button"
          disabled={busy || !draft.trim()}
          data-todo-tag-create-submit="true"
          onClick={() => void createTag()}
          className="inline-flex min-h-9 shrink-0 items-center gap-1 rounded-md bg-accent px-2.5 text-xs font-medium text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
        >
          <Plus className="size-3.5" aria-hidden="true" />
          <span>新建</span>
        </button>
      </div>

      {error && (
        <p role="alert" data-todo-tag-error="true" className="text-xs text-danger">
          {error}
        </p>
      )}
    </section>
  );
}

type SlotContribution = {
  readonly name: string;
  readonly component: ComponentType<never>;
  readonly order: number;
};

/**
 * Mounts a component into a host slot. The client context exposes the slot
 * registry under a small, stable set of entry points; resolve the first one the
 * host actually provides so the plugin keeps working across SDK revisions.
 */
function mountInSlot(ctx: Context, contribution: SlotContribution): void {
  const host = ctx as unknown as {
    readonly slot?: { readonly register?: unknown };
    readonly slots?: { readonly register?: unknown };
    readonly router?: { readonly registerSlot?: unknown };
    readonly registerSlot?: unknown;
  };
  const candidates: ReadonlyArray<{
    readonly owner: unknown;
    readonly register: unknown;
  }> = [
    { owner: host.slot, register: host.slot?.register },
    { owner: host.slots, register: host.slots?.register },
    { owner: host.router, register: host.router?.registerSlot },
    { owner: host, register: host.registerSlot },
  ];

  const { name, component, order } = contribution;
  for (const { owner, register } of candidates) {
    if (typeof register !== "function") continue;
    const fn = register as (this: unknown, ...args: unknown[]) => unknown;
    try {
      fn.call(owner, { name, component, order });
      return;
    } catch {
      // Fall through to the positional signature.
    }
    try {
      fn.call(owner, name, { component, order });
      return;
    } catch {
      // Try the next candidate entry point.
    }
  }
  console.warn(`[todo-tags] Unable to mount a component into slot "${name}".`);
}

export default function apply(ctx: Context): void {
  mountInSlot(ctx, {
    name: "todo.item.badges",
    component: TaskTagBadges,
    order: 10,
  });
  mountInSlot(ctx, {
    name: "todo.item.detail",
    component: TaskTagEditor,
    order: 10,
  });
}
