type SlotEntry = { readonly name: string; readonly component: ComponentType<never>; readonly order: number };

type SlotServiceLike = {
  register?: (...args: unknown[]) => unknown;
};

function describeSlotService(service: object): string {
  const keys = new Set<string>();
  let current: object | null = service;
  while (current && current !== Object.prototype) {
    for (const key of Object.getOwnPropertyNames(current)) keys.add(key);
    current = Object.getPrototypeOf(current) as object | null;
  }
  return [...keys].sort().join(", ");
}

function mountInSlot(ctx: Context, entry: SlotEntry): void {
  const service = (ctx as unknown as { slot?: SlotServiceLike }).slot;
  if (!service || typeof service.register !== "function") {
    throw new Error(`[todo-tags] client slot service cannot mount "${entry.name}"; members: ${service ? describeSlotService(service) : "missing"}`);
  }
  const { name, component, order } = entry;
  const register = service.register.bind(service) as (...args: unknown[]) => unknown;
  const attempts: ReadonlyArray<() => unknown> = [
    () => register({ name, component, order }),
    () => register(name, { component, order }),
    () => register(name, component),
  ];
  let lastError: unknown = null;
  for (const attempt of attempts) {
    try { attempt(); return; } catch (error) { lastError = error; }
  }
  throw new Error(`[todo-tags] failed to mount slot "${name}": ${lastError instanceof Error ? lastError.message : String(lastError)}`);
}

