", "sourceFiles": {"server.ts": "import { Service, type Context } from "cordis";
import type { ScopedDb } from "@host/server-sdk";
import type {
  CreateTagInput,
  Tag,
  TagColor,
  TagService,
} from "./contract.d.ts";

const TAG_COLORS: readonly TagColor[] = [
  "slate",
  "blue",
  "green",
  "amber",
  "rose",
  "violet",
];

const DEFAULT_TAG_COLOR: TagColor = "slate";
const MAX_TAG_NAME_LENGTH = 32;

const TAG_COLUMNS = "id, name, color, created_at";

interface TagRow {
  readonly id: string;
  readonly name: string;
  readonly color: string;
  readonly created_at: string;
}

function isTagColor(value: unknown): value is TagColor {
  return (
    typeof value === "string" && (TAG_COLORS as readonly string[]).includes(value)
  );
}

function toTag(row: TagRow): Tag {
  return {
    id: row.id,
    name: row.name,
    color: isTagColor(row.color) ? row.color : DEFAULT_TAG_COLOR,
    createdAt: row.created_at,
  };
}

function normalizeTagName(raw: string): string {
  return raw.trim().replace(/\s+/g, " ");
}

function httpError(status: number, message: string): Error & { status: number } {
  const error = new Error(message) as Error & { status: number };
  error.status = status;
  return error;
}

export default class TodoTagsService extends Service implements TagService {
  private readonly db: ScopedDb;

  constructor(ctx: Context) {
    super(ctx, "tags");
    this.db = ctx.db;

    this.db.exec(`
      CREATE TABLE IF NOT EXISTS plg_todo_tags__tags (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        name_key TEXT NOT NULL UNIQUE,
        color TEXT NOT NULL DEFAULT 'slate',
        created_at TEXT NOT NULL
      )
    `);
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS plg_todo_tags__task_tags (
        task_id TEXT NOT NULL,
        tag_id TEXT NOT NULL,
        created_at TEXT NOT NULL,
        PRIMARY KEY (task_id, tag_id)
      )
    `);
    this.db.exec(
      "CREATE INDEX IF NOT EXISTS plg_todo_tags__task_tags_by_task ON plg_todo_tags__task_tags (task_id)",
    );

    ctx.http.route("GET", "/tags", () => ({ tags: this.list() }));

    ctx.http.route("POST", "/tags", (req) => {
      const body = (req.body ?? {}) as { name?: unknown; color?: unknown };
      if (typeof body.name !== "string") {
        return { status: 400, body: { error: "Tag name is required" } };
      }
      if (body.color !== undefined && !isTagColor(body.color)) {
        return {
          status: 400,
          body: { error: `Invalid tag color: ${String(body.color)}` },
        };
      }
      const name = normalizeTagName(body.name);
      if (!name) {
        return { status: 400, body: { error: "Tag name is required" } };
      }
      if (name.length > MAX_TAG_NAME_LENGTH) {
        return {
          status: 400,
          body: {
            error: `Tag name must be at most ${MAX_TAG_NAME_LENGTH} characters`,
          },
        };
      }
      if (this.findByName(name)) {
        return { status: 409, body: { error: `Tag already exists: ${name}` } };
      }
      return { status: 201, body: { tag: this.create({ name, color: body.color }) } };
    });

    ctx.http.route("DELETE", "/tags/:id", (req) => {
      if (!this.delete(req.params.id)) {
        return { status: 404, body: { error: "Tag not found" } };
      }
      return { deleted: true, id: req.params.id };
    });

    ctx.http.route("GET", "/tasks/:taskId/tags", (req) => ({
      taskId: req.params.taskId,
      tags: this.listForTask(req.params.taskId),
    }));

    ctx.http.route("POST", "/tasks/:taskId/tags", (req) => {
      const body = (req.body ?? {}) as { tagId?: unknown };
      if (typeof body.tagId !== "string" || body.tagId.length === 0) {
        return { status: 400, body: { error: "tagId is required" } };
      }
      if (!this.get(body.tagId)) {
        return { status: 404, body: { error: "Tag not found" } };
      }
      return { tags: this.attach(req.params.taskId, body.tagId) };
    });

    ctx.http.route("PUT", "/tasks/:taskId/tags", (req) => {
      const body = (req.body ?? {}) as { tagIds?: unknown };
      if (
        !Array.isArray(body.tagIds) ||
        body.tagIds.some((value) => typeof value !== "string")
      ) {
        return {
          status: 400,
          body: { error: "tagIds must be an array of tag ids" },
        };
      }
      const tagIds = Array.from(new Set(body.tagIds as string[]));
      const unknownIds = tagIds.filter((id) => !this.get(id));
      if (unknownIds.length > 0) {
        return {
          status: 400,
          body: { error: `Unknown tag ids: ${unknownIds.join(", ")}` },
        };
      }
      return { tags: this.setForTask(req.params.taskId, tagIds) };
    });

    ctx.http.route("DELETE", "/tasks/:taskId/tags/:tagId", (req) => ({
      tags: this.detach(req.params.taskId, req.params.tagId),
    }));
  }

  list(): Tag[] {
    const rows = this.db
      .prepare(
        `SELECT ${TAG_COLUMNS} FROM plg_todo_tags__tags ORDER BY name_key ASC`,
      )
      .all<TagRow>();
    return rows.map(toTag);
  }

  get(id: string): Tag | null {
    const row = this.db
      .prepare(`SELECT ${TAG_COLUMNS} FROM plg_todo_tags__tags WHERE id = ?`)
      .get<TagRow>(id);
    return row ? toTag(row) : null;
  }

  create(input: string | CreateTagInput): Tag {
    const rawName = typeof input === "string" ? input : input.name;
    const name = normalizeTagName(rawName ?? "");
    if (!name) {
      throw httpError(400, "Tag name is required");
    }
    if (name.length > MAX_TAG_NAME_LENGTH) {
      throw httpError(
        400,
        `Tag name must be at most ${MAX_TAG_NAME_LENGTH} characters`,
      );
    }
    const color =
      typeof input === "string" ? DEFAULT_TAG_COLOR : (input.color ?? DEFAULT_TAG_COLOR);
    if (!isTagColor(color)) {
      throw httpError(400, `Invalid tag color: ${String(color)}`);
    }
    if (this.findByName(name)) {
      throw httpError(409, `Tag already exists: ${name}`);
    }

    const now = new Date().toISOString();
    const id = globalThis.crypto.randomUUID();
    this.db
      .prepare(
        "INSERT INTO plg_todo_tags__tags (id, name, name_key, color, created_at) VALUES (?, ?, ?, ?, ?)",
      )
      .run(id, name, name.toLowerCase(), color, now);

    this.emitChanged(null, [id]);
    return this.get(id)!;
  }

  delete(id: string): boolean {
    if (!this.get(id)) return false;

    this.db
      .prepare("DELETE FROM plg_todo_tags__task_tags WHERE tag_id = ?")
      .run(id);
    const result = this.db
      .prepare("DELETE FROM plg_todo_tags__tags WHERE id = ?")
      .run(id);
    const deleted = Number(result.changes) > 0;
    if (deleted) {
      this.emitChanged(null, [id]);
    }
    return deleted;
  }

  listForTask(taskId: string): Tag[] {
    const rows = this.db
      .prepare(
        `SELECT t.id, t.name, t.color, t.created_at
           FROM plg_todo_tags__task_tags AS tt
           JOIN plg_todo_tags__tags AS t ON t.id = tt.tag_id
          WHERE tt.task_id = ?
          ORDER BY t.name_key ASC`,
      )
      .all<TagRow>(taskId);
    return rows.map(toTag);
  }

  attach(taskId: string, tagId: string): Tag[] {
    if (!this.get(tagId)) {
      throw httpError(404, "Tag not found");
    }
    const alreadyAttached = this.listForTask(taskId).some(
      (tag) => tag.id === tagId,
    );
    if (!alreadyAttached) {
      this.db
        .prepare(
          "INSERT OR IGNORE INTO plg_todo_tags__task_tags (task_id, tag_id, created_at) VALUES (?, ?, ?)",
        )
        .run(taskId, tagId, new Date().toISOString());
      this.emitChanged(taskId, this.listForTask(taskId).map((tag) => tag.id));
    }
    return this.listForTask(taskId);
  }

  detach(taskId: string, tagId: string): Tag[] {
    this.db
      .prepare(
        "DELETE FROM plg_todo_tags__task_tags WHERE task_id = ? AND tag_id = ?",
      )
      .run(taskId, tagId);
    const tags = this.listForTask(taskId);
    this.emitChanged(taskId, tags.map((tag) => tag.id));
    return tags;
  }

  setForTask(taskId: string, tagIds: readonly string[]): Tag[] {
    const unique = Array.from(new Set(tagIds));
    for (const tagId of unique) {
      if (!this.get(tagId)) {
        throw httpError(400, `Unknown tag id: ${tagId}`);
      }
    }

    this.db
      .prepare("DELETE FROM plg_todo_tags__task_tags WHERE task_id = ?")
      .run(taskId);
    const now = new Date().toISOString();
    for (const tagId of unique) {
      this.db
        .prepare(
          "INSERT OR IGNORE INTO plg_todo_tags__task_tags (task_id, tag_id, created_at) VALUES (?, ?, ?)",
        )
        .run(taskId, tagId, now);
    }

    const tags = this.listForTask(taskId);
    this.emitChanged(taskId, tags.map((tag) => tag.id));
    return tags;
  }

  private findByName(name: string): Tag | null {
    const row = this.db
      .prepare(
        `SELECT ${TAG_COLUMNS} FROM plg_todo_tags__tags WHERE name_key = ?`,
      )
      .get<TagRow>(name.toLowerCase());
    return row ? toTag(row) : null;
  }

  private emitChanged(taskId: string | null, tagIds: readonly string[]): void {
    this.ctx.emit("tags:changed", { taskId, tagIds });
  }
}
