import type { PluginTestContext } from "@host/server-sdk";

interface TagPayload {
  readonly tag: { readonly id: string; readonly name: string; readonly color: string };
}

interface TagListPayload {
  readonly tags: ReadonlyArray<{ readonly id: string; readonly name: string }>;
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = globalThis.crypto.randomUUID().slice(0, 8);
  const tagName = `Urgent-${suffix}`;
  const taskId = `contract-task-${suffix}`;

  const created = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: tagName, color: "rose" },
  });
  assert.equal(created.status, 201);
  const tag = (created.body as TagPayload).tag;
  assert.equal(tag.name, tagName);
  assert.equal(tag.color, "rose");

  const duplicate = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: tagName.toUpperCase() },
  });
  assert.equal(duplicate.status, 409);

  const invalid = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: "   " },
  });
  assert.equal(invalid.status, 400);

  const attached = await ctx.request({
    method: "POST",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagId: tag.id },
  });
  assert.equal(attached.status, 200);
  assert.deepEqual(
    (attached.body as TagListPayload).tags.map((item) => item.id),
    [tag.id],
  );

  const listed = await ctx.request({
    method: "GET",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
  });
  assert.equal(listed.status, 200);
  assert.deepEqual(
    (listed.body as TagListPayload).tags.map((item) => item.name),
    [tagName],
  );

  const catalog = await ctx.request({ method: "GET", path: "/api/app/todo-tags/tags" });
  assert.equal(catalog.status, 200);
  assert.ok((catalog.body as TagListPayload).tags.some((item) => item.id === tag.id));

  const replaced = await ctx.request({
    method: "PUT",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagIds: [] },
  });
  assert.equal(replaced.status, 200);
  assert.equal((replaced.body as TagListPayload).tags.length, 0);

  const unknownTag = await ctx.request({
    method: "PUT",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagIds: ["missing-tag"] },
  });
  assert.equal(unknownTag.status, 400);

  const sprint = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: `Sprint-${suffix}` },
  });
  assert.equal(sprint.status, 201);
  const sprintId = (sprint.body as TagPayload).tag.id;

  await ctx.request({
    method: "POST",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagId: sprintId },
  });

  const removed = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tags/${sprintId}`,
  });
  assert.equal(removed.status, 200);

  const afterRemoval = await ctx.request({
    method: "GET",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
  });
  assert.deepEqual((afterRemoval.body as TagListPayload).tags, []);

  const missing = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tags/${sprintId}`,
  });
  assert.equal(missing.status, 404);

  await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tags/${tag.id}`,
  });
}
