function isCounts(value: unknown): value is TodoCounts { ... }

export function TodoHeaderCounter({ tasks }: TodoCounterSlotProps) { ... }

type SlotEntry = { name: string; component: ComponentType<TodoCounterSlotProps>; order: number };

interface SlotServiceLike { register?: (...args: unknown[]) => unknown }

function errorMessage(error: unknown): string { ... }

function mountInSlot(ctx: Context, entry: SlotEntry): void {
  const service = (ctx as unknown as { readonly slot?: SlotServiceLike }).slot;
  if (!service || typeof service.register !== "function") {
    throw new Error(`[todo-counter] slot service is unavailable; cannot mount "${entry.name}"`);
  }
  const register = service.register.bind(service) as (...args: unknown[]) => unknown;
  const { name, component, order } = entry;
  try {
    register({ name, component, order });
  } catch (error) {
    try {
      register(name, { component, order });
    } catch {
      throw new Error(`[todo-counter] failed to mount slot "${name}": ${errorMessage(error)}`);
    }
  }
}

export const inject = ["slot"];

export default function apply(ctx: Context): void {
  ctx.inject(["slot"], (scoped) => {
    mountInSlot(scoped as Context, { name: "todo.header.actions", component: TodoHeaderCounter, order: 0 });
  });
}
