import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface CountsBody { readonly counts: { readonly open: number; readonly done: number; readonly total: number } }

export default async function (ctx: PluginTestContext): Promise<void> {
  const before = await ctx.request({ method: "GET", path: "/api/app/todo-counter/counts" });
  assert.equal(before.status, 200);
  const base = (before.body as CountsBody).counts;
  assert.equal(base.open + base.done, base.total);

  const first = await ctx.request({ method: "POST", path: "/api/app/todo-core/tasks", body: { title: "Counter open task" } });
  assert.equal(first.status, 201);
  const second = await ctx.request({ method: "POST", path: "/api/app/todo-core/tasks", body: { title: "Counter done task" } });
  assert.equal(second.status, 201);
  const secondId = (second.body as { task: { id: string } }).task.id;

  const done = await ctx.request({ method: "POST", path: `/api/app/todo-core/tasks/${secondId}/transition`, body: { nextState: "done" } });
  assert.equal(done.status, 200);

  const after = await ctx.request({ method: "GET", path: "/api/app/todo-counter/counts" });
  assert.equal(after.status, 200);
  const next = (after.body as CountsBody).counts;
  assert.equal(next.open, base.open + 1);
  assert.equal(next.done, base.done + 1);
  assert.equal(next.total, base.total + 2);
}
```

