import {
  useCallback,
  useEffect,
  useState,
  type ComponentType,
} from "react";
import type { Context } from "cordis";
import { Check, Plus, Tag as TagIcon } from "lucide-react";
import type { Tag, TagColor, TagSlotProps } from "./contract.d.ts";

const TAGS_CHANGED_EVENT = "todo-tags:changed";

const TAG_COLORS: readonly TagColor[] = [
  "slate",
  "blue",
  "green",
  "amber",
  "rose",
  "violet",
];

const TAG_COLOR_HEX: Record<TagColor, string> = {
  slate: "#64748b",
  blue: "#2563eb",
  green: "#15803d",
  amber: "#b45309",
  rose: "#be123c",
  violet: "#7c3aed",
};

const TAG_COLOR_LABELS: Record<TagColor, string> = {
  slate: "灰",
  blue: "蓝",
  green: "绿",
  amber: "琥珀",
  rose: "玫红",
  violet: "紫",
};

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function chipStyle(color: TagColor) {
  const hex = TAG_COLOR_HEX[color] ?? TAG_COLOR_HEX.slate;
  return {
    color: hex,
    borderColor: `${hex}66`,
    backgroundColor: `${hex}14`,
  };
}

function tagsChanged(): void {
  window.dispatchEvent(new Event(TAGS_CHANGED_EVENT));
}

const TASK_TAGS_URL = (taskId: string) =>
  `/api/app/todo-tags/tasks/${encodeURIComponent(taskId)}/tags`;

/** Read-only chips rendered inline in every task row. */
export function TaskTagBadges({ task }: TagSlotProps) {
  const [tags, setTags] = useState<readonly Tag[]>([]);

  const load = useCallback(async () => {
    try {
      const data = await requestJson<{ tags: Tag[] }>(TASK_TAGS_URL(task.id));
      setTags(Array.isArray(data.tags) ? data.tags : []);
    } catch {
      setTags([]);
    }
  }, [task.id]);

  useEffect(() => {
    void load();
  }, [load]);

  useEffect(() => {
    const handleChanged = () => {
      void load();
    };
    window.addEventListener(TAGS_CHANGED_EVENT, handleChanged);
    return () => window.removeEventListener(TAGS_CHANGED_EVENT, handleChanged);
  }, [load]);

  if (tags.length === 0) return null;

  return (
    <span
      data-todo-tags-badges={task.id}
      className="flex flex-wrap items-center gap-1"
    >
      {tags.map((tag) => (
        <span
          key={tag.id}
          data-todo-tag-badge={tag.id}
          title={`标签：${tag.name}`}
          style={chipStyle(tag.color)}
          className="inline-flex max-w-[9rem] items-center rounded-full border px-2 py-0.5 text-[11px] leading-5 font-medium"
        >
          <span className="truncate">{tag.name}</span>
        </span>
      ))}
    </span>
  );
}

/** Tag picker + inline tag creation, rendered inside the task detail panel. */
export function TaskTagEditor({ task }: TagSlotProps) {
  const [allTags, setAllTags] = useState<readonly Tag[]>([]);
  const [selectedIds, setSelectedIds] = useState<readonly string[]>([]);
  const [draft, setDraft] = useState("");
  const [draftColor, setDraftColor] = useState<TagColor>("blue");
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    try {
      const [catalog, assigned] = await Promise.all([
        requestJson<{ tags: Tag[] }>("/api/app/todo-tags/tags"),
        requestJson<{ tags: Tag[] }>(TASK_TAGS_URL(task.id)),
      ]);
      setAllTags(Array.isArray(catalog.tags) ? catalog.tags : []);
      setSelectedIds(
        Array.isArray(assigned.tags) ? assigned.tags.map((tag) => tag.id) : [],
      );
      setError("");
    } catch (err) {
      setError(errorMessage(err));
    } finally {
      setLoading(false);
    }
  }, [task.id]);

  useEffect(() => {
    setLoading(true);
    void load();
  }, [load]);

  const replaceSelection = useCallback(
    async (tagIds: readonly string[]) => {
      setBusy(true);
      try {
        const data = await requestJson<{ tags: Tag[] }>(TASK_TAGS_URL(task.id), {
          method: "PUT",
          body: JSON.stringify({ tagIds }),
        });
        setSelectedIds(
          Array.isArray(data.tags) ? data.tags.map((tag) => tag.id) : [],
        );
        setError("");
        tagsChanged();
      } catch (err) {
        setError(errorMessage(err));
      } finally {
        setBusy(false);
      }
    },
    [task.id],
  );

  const toggleTag = (tagId: string) => {
    if (busy) return;
    const next = selectedIds.includes(tagId)
      ? selectedIds.filter((id) => id !== tagId)
      : [...selectedIds, tagId];
    void replaceSelection(next);
  };

  const createTag = async () => {
    const name = draft.trim();
    if (!name || busy) return;
    setBusy(true);
    setError("");
    try {
      const created = await requestJson<{ tag: Tag }>(
        "/api/app/todo-tags/tags",
        {
          method: "POST",
          body: JSON.stringify({ name, color: draftColor }),
        },
      );
      const newTagId = created.tag?.id;
      if (newTagId) {
        await requestJson<{ tags: Tag[] }>(TASK_TAGS_URL(task.id), {
          method: "PUT",
          body: JSON.stringify({ tagIds: [...selectedIds, newTagId] }),
        });
      }
      setDraft("");
      await load();
      tagsChanged();
    } catch (err) {
      setError(errorMessage(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <section data-todo-tag-editor={task.id} className="space-y-2">
      <div className="flex items-center justify-between gap-2">
        <h3 className="flex items-center gap-1.5 text-xs font-medium text-muted">
          <TagIcon className="size-3.5" aria-hidden="true" />
          <span>标签</span>
        </h3>
        <span className="text-[11px] tabular-nums text-muted">
          已选 {selectedIds.length}
        </span>
      </div>

      {loading ? (
        <p className="text-xs text-muted">正在加载标签…</p>
      ) : allTags.length === 0 ? (
        <p className="text-xs text-muted">还没有标签，先创建一个。</p>
      ) : (
        <div className="flex flex-wrap gap-1.5">
          {allTags.map((tag) => {
            const active = selectedIds.includes(tag.id);
            return (
              <button
                key={tag.id}
                type="button"
                disabled={busy}
                aria-pressed={active}
                data-todo-tag-toggle={tag.id}
                data-todo-tag-active={active ? "true" : "false"}
                onClick={() => toggleTag(tag.id)}
                style={active ? chipStyle(tag.color) : undefined}
                className={`inline-flex min-h-9 max-w-[10rem] items-center gap-1 rounded-full border px-2.5 py-1 text-[11px] font-medium transition-colors disabled:opacity-45 ${
                  active
                    ? "border-transparent"
                    : "border-line bg-surface text-muted hover:border-accent/40 hover:text-ink"
                }`}
              >
                {active && <Check className="size-3" aria-hidden="true" />}
                <span className="truncate">{tag.name}</span>
              </button>
            );
          })}
        </div>
      )}

      {/* No nested <form>: this slot renders inside the task detail form. */}
      <div className="flex items-center gap-1.5">
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault();
              void createTag();
            }
          }}
          placeholder="新标签名称"
          aria-label="新标签名称"
          data-todo-tag-create-input="true"
          className="min-h-9 min-w-0 flex-1 rounded-md border border-line bg-surface px-2.5 py-1.5 text-xs text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
        />
        <select
          value={draftColor}
          onChange={(event) => setDraftColor(event.target.value as TagColor)}
          aria-label="标签颜色"
          data-todo-tag-color-select="true"
          className="min-h-9 rounded-md border border-line bg-surface px-1.5 py-1.5 text-xs text-ink outline-none focus:border-accent"
        >
          {TAG_COLORS.map((color) => (
            <option key={color} value={color}>
              {TAG_COLOR_LABELS[color]}
            </option>
          ))}
        </select>
        <button
          type="button"
          disabled={busy || !draft.trim()}
          data-todo-tag-create-submit="true"
          onClick={() => void createTag()}
          className="inline-flex min-h-9 shrink-0 items-center gap-1 rounded-md bg-accent px-2.5 text-xs font-medium text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
        >
          <Plus className="size-3.5" aria-hidden="true" />
          <span>新建</span>
        </button>
      </div>

      {error && (
        <p role="alert" data-todo-tag-error="true" className="text-xs text-danger">
          {error}
        </p>
      )}
    </section>
  );
}

type SlotEntry = {
  readonly name: string;
  readonly component: ComponentType<never>;
  readonly order: number;
};

interface SlotServiceLike {
  readonly register?: (...args: unknown[]) => unknown;
}

function describeMembers(value: object): string {
  const members = new Set<string>();
  let current: object | null = value;
  while (current && current !== Object.prototype) {
    for (const key of Object.getOwnPropertyNames(current)) members.add(key);
    current = Object.getPrototypeOf(current) as object | null;
  }
  return Array.from(members).sort().join(", ");
}

/** Mounts a component into a slot published through the client `slot` service. */
function mountInSlot(ctx: Context, entry: SlotEntry): void {
  const service = (ctx as unknown as { readonly slot?: SlotServiceLike }).slot;
  if (!service || typeof service.register !== "function") {
    throw new Error(
      `[todo-tags] cannot mount slot "${entry.name}": slot service members = ${
        service ? describeMembers(service) : "missing"
      }`,
    );
  }

  const { name, component, order } = entry;
  const register = service.register.bind(service) as (
    ...args: unknown[]
  ) => unknown;
  const attempts: ReadonlyArray<() => unknown> = [
    () => register({ name, component, order }),
    () => register(name, { component, order }),
    () => register(name, component),
  ];

  let lastError: unknown = null;
  for (const attempt of attempts) {
    try {
      attempt();
      return;
    } catch (error) {
      lastError = error;
    }
  }
  throw new Error(
    `[todo-tags] failed to mount slot "${name}": ${errorMessage(lastError)}`,
  );
}

/** `slot` is a client service, so the plugin must declare the injection. */
export const inject = ["slot"];

export default function apply(ctx: Context): void {
  ctx.inject(["slot"], (scoped) => {
    mountInSlot(scoped as Context, {
      name: "todo.item.badges",
      component: TaskTagBadges,
      order: 10,
    });
    mountInSlot(scoped as Context, {
      name: "todo.item.detail",
      component: TaskTagEditor,
      order: 10,
    });
  });
}

