import {
  useCallback,
  useEffect,
  useMemo,
  useState,
  type FormEvent,
} from "react";
import type { Context } from "cordis";
import {
  Check,
  CheckCheck,
  Circle,
  Compass,
  ListTodo,
  Plus,
  Search,
  Trash2,
  X,
} from "lucide-react";
import { Button } from "@base-ui/react";
import {
  Slot,
  dispatchClientBail,
  useClientContext,
  useClientRoutes,
  useNavigate,
} from "@host/client-sdk";
import type { TaskItem, TaskState } from "./contract.d.ts";

type FilterKind = "open" | "done" | "all";

const FILTERS: ReadonlyArray<{
  readonly id: FilterKind;
  readonly label: string;
}> = [
  { id: "open", label: "任务" },
  { id: "done", label: "已完成" },
  { id: "all", label: "全部任务" },
];

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

function FilterIcon({ id }: { readonly id: FilterKind }) {
  if (id === "open") return <ListTodo className="size-4" aria-hidden="true" />;
  if (id === "done")
    return <CheckCheck className="size-4" aria-hidden="true" />;
  return <Circle className="size-4" aria-hidden="true" />;
}

