            <nav
              aria-label="扩展视图"
              className="flex flex-wrap gap-1.5 md:flex-col md:gap-1"
            >
              {extraRoutes.map((route) => (
                <button
                  key={route.path}
                  type="button"
                  onClick={() => navigate(route.path)}
