  const visibleTasks = useMemo(() => {
    const keyword = search.trim().toLowerCase();
    return tasks.filter((task) => {
      if (filter !== "all" && task.state !== filter) return false;
      if (!keyword) return true;
      return (
        task.title.toLowerCase().includes(keyword) ||
        task.notes.toLowerCase().includes(keyword)
      );
    });
  }, [tasks, filter, search]);

  const extraRoutes = useMemo(
    () => routes.filter((route) => route.path !== "/" && route.navLabel),
    [routes],
  );

  const handleAddTask = async (event: FormEvent) => {
    event.preventDefault();
    const submitted = draft;
    const title = submitted.trim();
    if (!title || busy) return;
    setBusy(true);
    setError("");
    try {
      await requestJson<{ task: TaskItem }>("/api/app/todo-core/tasks", {
        method: "POST",
        body: JSON.stringify({ title }),
      });
      setDraft((current) => (current === submitted ? "" : current));
      if (filter === "done") {
        setFilter("open");
      }
      await refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  const handleTransition = async (task: TaskItem, nextState: TaskState) => {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      const meta: Record<string, unknown> = {};
      // Generic client seam: extensions may veto or enrich `meta` before the
      // transition request leaves the browser. todo-core stays feature agnostic.
      for (const interceptor of Array.from(transitionInterceptors.current)) {
