import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface Tag {
  readonly id: string;
  readonly name: string;
  readonly color: string;
  readonly createdAt: string;
}

interface TagPayload {
  readonly tag: Tag;
  readonly deduplicated: boolean;
}

interface TagListPayload {
  readonly tags: readonly Tag[];
}

function tagsOf(body: unknown): readonly Tag[] {
  return (body as TagListPayload).tags;
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = globalThis.crypto.randomUUID().slice(0, 8);
  const taskId = `contract-task-${suffix}`;

  const initialCatalog = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/tags",
  });
  assert.equal(initialCatalog.status, 200);
  const preexisting = tagsOf(initialCatalog.body);

  // Newly saved tags are lowercased and whitespace-collapsed.
  const rawName = `  Release   Notes-${suffix}  `;
  const normalizedName = `release notes-${suffix}`;
  const created = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: rawName, color: "rose" },
  });
  assert.equal(created.status, 201);
  const createdPayload = created.body as TagPayload;
  assert.equal(createdPayload.deduplicated, false);
  const tag = createdPayload.tag;
  assert.equal(tag.name, normalizedName);
  assert.equal(tag.color, "rose");

  // Saving a case/whitespace variant deduplicates instead of inserting a row.
  const deduped = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: `  RELEASE  NOTES-${suffix.toUpperCase()} `, color: "blue" },
  });
  assert.equal(deduped.status, 200);
  const dedupedPayload = deduped.body as TagPayload;
  assert.equal(dedupedPayload.deduplicated, true);
  assert.equal(dedupedPayload.tag.id, tag.id);
  // The stored row is returned as-is: casing, color and timestamp untouched.
  assert.equal(dedupedPayload.tag.name, normalizedName);
  assert.equal(dedupedPayload.tag.color, "rose");
  assert.equal(dedupedPayload.tag.createdAt, tag.createdAt);

  const catalog = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/tags",
  });
  assert.equal(catalog.status, 200);
  const matches = tagsOf(catalog.body).filter(
    (item) => item.name.toLowerCase() === normalizedName,
  );
  assert.equal(matches.length, 1);
  assert.equal(matches[0].id, tag.id);

  // Validation still applies to raw input.
  const blank = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: "   " },
  });
  assert.equal(blank.status, 400);

  const tooLong = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: "a".repeat(33) },
  });
  assert.equal(tooLong.status, 400);

  const badColor = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: `Bad-Color-${suffix}`, color: "pink" },
  });
  assert.equal(badColor.status, 400);

  // Task associations use the normalized tag and stay deduplicated.
  const attached = await ctx.request({
    method: "POST",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagId: tag.id },
  });
  assert.equal(attached.status, 200);
  assert.deepEqual(tagsOf(attached.body).map((item) => item.id), [tag.id]);

  const attachedAgain = await ctx.request({
    method: "POST",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagId: tag.id },
  });
  assert.equal(attachedAgain.status, 200);
  assert.deepEqual(tagsOf(attachedAgain.body).map((item) => item.id), [tag.id]);

  const listed = await ctx.request({
    method: "GET",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
  });
  assert.equal(listed.status, 200);
  assert.deepEqual(tagsOf(listed.body).map((item) => item.name), [normalizedName]);

  const replaced = await ctx.request({
    method: "PUT",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagIds: [tag.id, tag.id] },
  });
  assert.equal(replaced.status, 200);
  assert.deepEqual(tagsOf(replaced.body).map((item) => item.id), [tag.id]);

  const unknownTag = await ctx.request({
    method: "PUT",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagIds: ["missing-tag"] },
  });
  assert.equal(unknownTag.status, 400);

  // Deleting the tag clears the association; a second delete is a 404.
  const removed = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tags/${tag.id}`,
  });
  assert.equal(removed.status, 200);

  const afterRemoval = await ctx.request({
    method: "GET",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
  });
  assert.deepEqual(tagsOf(afterRemoval.body), []);

  const missing = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tags/${tag.id}`,
  });
  assert.equal(missing.status, 404);

  // Historical rows are never rewritten: every pre-existing tag is unchanged.
  const finalCatalog = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/tags",
  });
  assert.equal(finalCatalog.status, 200);
  const finalTags = tagsOf(finalCatalog.body);
  for (const before of preexisting) {
    const after = finalTags.find((item) => item.id === before.id);
    assert.deepEqual(after, before);
  }
}

