import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface CountsPayload {
  readonly counts: {
    readonly open: number;
    readonly done: number;
    readonly total: number;
  };
}

function countsOf(body: unknown): CountsPayload["counts"] {
  return (body as CountsPayload).counts;
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const baseline = await ctx.request({
    method: "GET",
    path: "/api/app/todo-counter/counts",
  });
  assert.equal(baseline.status, 200);
  const before = countsOf(baseline.body);
  assert.equal(before.total, before.open + before.done);

  const pending = await ctx.request({
    method: "POST",
    path: "/api/app/todo-core/tasks",
    body: { title: "Counter pending task" },
  });
  assert.equal(pending.status, 201);

  const completed = await ctx.request({
    method: "POST",
    path: "/api/app/todo-core/tasks",
    body: { title: "Counter completed task" },
  });
  assert.equal(completed.status, 201);
  const completedId = (completed.body as { task: { id: string } }).task.id;

  const transitioned = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${completedId}/transition`,
    body: { nextState: "done" },
  });
  assert.equal(transitioned.status, 200);

  const after = await ctx.request({
    method: "GET",
    path: "/api/app/todo-counter/counts",
  });
  assert.equal(after.status, 200);
  const next = countsOf(after.body);

  assert.equal(next.open, before.open + 1);
  assert.equal(next.done, before.done + 1);
  assert.equal(next.total, before.total + 2);
  assert.equal(next.total, next.open + next.done);
}

