        const request: PendingReview = {
          taskId: task.id,
          title: task.title?.trim() || "该任务",
          resolve: (collected) => {
            if (collected === null) {
              resolve("已取消复盘，任务未完成");
              return;
            }
            meta.review = { summary: collected };
            resolve();
          },
        };
        pendingRef.current = request;
        setSummary("");
        setError("");
        setPending(request);
