    const text = summary.trim();
    if (!text) {
      setError("请填写复盘总结后再完成任务");
      return;
    }
    if (text.length > MAX_SUMMARY_LENGTH) {
      setError(`复盘总结最多 ${MAX_SUMMARY_LENGTH} 个字符`);
      return;
    }
    settle(text);
  };

  if (!pending) return null;

  return (
    <div
      data-todo-review-dialog="true"
      role="dialog"
      aria-modal="true"
      aria-label="完成任务复盘"
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4"
