    setBusy(true);
    setError("");
    try {
      await requestJson<{ task: TaskItem }>("/api/app/todo-core/tasks", {
        method: "POST",
        body: JSON.stringify({ title }),
      });
      setDraft((current) => (current === submitted ? "" : current));
      if (filter === "done") {
        setFilter("open");
