        clientCtx,
        "todo:before-transition",
        { task, nextState, meta },
      );
      if (verdict === false) {
        setError("状态流转已被扩展规则阻止");
        return;
      }
      if (typeof verdict === "string" && verdict.length > 0) {
        setError(verdict);
        return;
