import { Service, type Context } from "cordis";
import type {} from "@host/server-sdk";
import type { TodoCounts, TodoCounterService } from "./contract.d.ts";

export default class TodoCounter
  extends Service
  implements TodoCounterService
{
  /** Counts are derived from todo-core, so wait for its `todo` service. */
  static inject = ["todo"];

  constructor(ctx: Context) {
    super(ctx, "todoCounter");

    ctx.http.route("GET", "/counts", () => ({ counts: this.counts() }));
  }

  counts(): TodoCounts {
    let open = 0;
    let done = 0;
    for (const task of this.ctx.todo.list()) {
      if (task.state === "done") {
        done += 1;
      } else {
        open += 1;
      }
    }
    return { open, done, total: open + done };
  }
}

