                            ? "border-accent bg-accent text-surface"
                            : "border-muted/60 bg-surface text-transparent hover:border-accent"
                        }`}
                      >
                        <Check className="size-3.5" aria-hidden="true" />
                      </span>
                    </button>

                    <button
