type FilterKind = "open" | "done" | "all";

const FILTERS: ReadonlyArray<{
  readonly id: FilterKind;
  readonly label: string;
}> = [
  { id: "open", label: "任务" },
  { id: "done", label: "已完成" },
  { id: "all", label: "全部任务" },
];

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

function FilterIcon({ id }: { readonly id: FilterKind }) {
  if (id === "open") return <ListTodo className="size-4" aria-hidden="true" />;
  if (id === "done")
    return <CheckCheck className="size-4" aria-hidden="true" />;
  return <Circle className="size-4" aria-hidden="true" />;
}

function TodoWorkspacePage() {
  const clientCtx = useClientContext();
  const routes = useClientRoutes();
  const navigate = useNavigate();

  const [tasks, setTasks] = useState<TaskItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<FilterKind>("open");
  const [search, setSearch] = useState("");
  const [draft, setDraft] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [selectedTaskId, setSelectedTaskId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState("");
  const [editNotes, setEditNotes] = useState("");

  /** Generic client-side transition interceptors registered by plugins. */
  const transitionInterceptors = useRef<Set<TodoTransitionInterceptor>>(
    new Set(),
  );

  const registerTransitionInterceptor = useCallback(
    (interceptor: TodoTransitionInterceptor) => {
      const registry = transitionInterceptors.current;
      registry.add(interceptor);
      return () => {
        registry.delete(interceptor);
      };
    },
    [],
  );

  const refresh = useCallback(async () => {
    try {
      const data = await requestJson<{ tasks: TaskItem[] }>(
        "/api/app/todo-core/tasks",
      );
      setTasks(data.tasks ?? []);
      setError("");
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const selectedTask = useMemo(
    () => tasks.find((t) => t.id === selectedTaskId) ?? null,
    [tasks, selectedTaskId],
  );

  useEffect(() => {
    if (selectedTask) {
      setEditTitle(selectedTask.title);
      setEditNotes(selectedTask.notes);
    }
  }, [selectedTask?.id, selectedTask?.title, selectedTask?.notes]);

  const counts = useMemo(() => {
    let open = 0;
    let done = 0;
    for (const task of tasks) {
      if (task.state === "done") done += 1;
