          <Slot
            name="todo.header.actions"
            props={{ tasks, filter, refresh }}
            className="flex items-center gap-2"
          />
        </div>

        <div className="px-6">
          <Slot
            name="todo.list.banner"
            props={{ tasks, filter, refresh }}
            className="mb-3 space-y-2"
          />
