  input: TodoReviewTransitionInput,
) => Promise<void | false | string> | void | false | string;

/** Props published by todo-core for `todo.transition.guard`. */
export interface TodoReviewGuardSlotProps {
  readonly registerTransitionInterceptor?: (
    interceptor: TodoReviewInterceptor,
  ) => () => void;
