/** Aggregate task counters derived from the todo store. */
export interface TodoCounts {
  readonly open: number;
  readonly done: number;
  readonly total: number;
}

/**
 * Read-only counting facade over the tasks owned by `todo-core`. The counter
 * never mutates the todo store; it only aggregates the public `todo` service.
 */
export interface TodoCounterService {
  counts(): TodoCounts;
}

/** Structural view of a task as handed to the `todo.header.actions` slot. */
export interface TodoCounterTask {
  readonly id: string;
  readonly state?: string;
}

/** Props published by todo-core for `todo.header.actions`. */
export interface TodoCounterSlotProps {
  readonly tasks?: readonly TodoCounterTask[];
  readonly filter?: "open" | "done" | "all";
  readonly refresh?: () => Promise<void> | void;
}

