    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  const activeFilterLabel =
    FILTERS.find((item) => item.id === filter)?.label ?? "任务";

  return (
    <div
      data-todo-core="true"
      className="flex min-h-0 flex-1 flex-col bg-canvas text-ink md:flex-row"
