async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/** Reads the summary already present in transition metadata, if any. */
function summaryFromMeta(
  meta: Record<string, unknown> | undefined,
): string | null {
  const raw = meta?.review;
  if (typeof raw === "string") return raw.trim();
  if (raw && typeof raw === "object") {
    const summary = (raw as { readonly summary?: unknown }).summary;
    if (typeof summary === "string") return summary.trim();
  }
  return null;
}

function useReview(task: TodoReviewTask): {
  readonly review: Review | null;
  readonly loading: boolean;
} {
  const [review, setReview] = useState<Review | null>(null);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    try {
      const data = await requestJson<{ review: Review | null }>(
        reviewUrl(task.id),
      );
      setReview(data.review ?? null);
    } catch {
      setReview(null);
    } finally {
      setLoading(false);
    }
  }, [task.id]);

  useEffect(() => {
    setLoading(true);
    void load();
  }, [load, task.updatedAt, task.state]);

  return { review, loading };
}

