      setReview(data.review ?? null);
    } catch {
      setReview(null);
    } finally {
      setLoading(false);
    }
  }, [task.id]);

  useEffect(() => {
    setLoading(true);
    void load();
  }, [load, task.updatedAt, task.state]);

  return { review, loading };
