import type { Context } from "cordis";
import { CheckCheck, X } from "lucide-react";
import type {
  Review,
  TodoReviewBadgeSlotProps,
  TodoReviewDetailSlotProps,
  TodoReviewGuardSlotProps,
  TodoReviewInterceptor,
  TodoReviewTransitionInput,
  TodoReviewTask,
} from "./contract.d.ts";

const REVIEWS_URL = "/api/app/todo-review/reviews";
const MAX_SUMMARY_LENGTH = 2000;

const reviewUrl = (taskId: string) =>
  `${REVIEWS_URL}/${encodeURIComponent(taskId)}`;

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/** Reads the summary already present in transition metadata, if any. */
function summaryFromMeta(
  meta: Record<string, unknown> | undefined,
): string | null {
  const raw = meta?.review;
  if (typeof raw === "string") return raw.trim();
  if (raw && typeof raw === "object") {
    const summary = (raw as { readonly summary?: unknown }).summary;
    if (typeof summary === "string") return summary.trim();
  }
  return null;
}

function useReview(task: TodoReviewTask): {
  readonly review: Review | null;
  readonly loading: boolean;
} {
  const [review, setReview] = useState<Review | null>(null);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    try {
      const data = await requestJson<{ review: Review | null }>(
        reviewUrl(task.id),
      );
      setReview(data.review ?? null);
    } catch {
      setReview(null);
    } finally {
      setLoading(false);
    }
  }, [task.id]);

  useEffect(() => {
    setLoading(true);
    void load();
  }, [load, task.updatedAt, task.state]);

  return { review, loading };
}

/** Compact "already reviewed" marker rendered inline in every task row. */
export function TodoReviewBadge({ task }: TodoReviewBadgeSlotProps) {
  const { review } = useReview(task);
  if (!review) return null;
  return (
    <span
      data-todo-review-badge={task.id}
      title={`已完成复盘：${review.summary}`}
      className="inline-flex max-w-[9rem] items-center gap-1 rounded-full border border-accent/30 bg-accent-soft px-2 py-0.5 text-[11px] leading-5 font-medium text-accent"
    >
      <CheckCheck className="size-3" aria-hidden="true" />
      <span className="truncate">已复盘</span>
    </span>
  );
}

/** Review summary shown inside the task detail panel. */
export function TodoReviewDetail({ task }: TodoReviewDetailSlotProps) {
  const { review, loading } = useReview(task);
  return (
    <section data-todo-review-detail={task.id} className="space-y-1.5">
      <h3 className="flex items-center gap-1.5 text-xs font-medium text-muted">
        <CheckCheck className="size-3.5" aria-hidden="true" />
        <span>复盘总结</span>
      </h3>
      {loading ? (
        <p className="text-xs text-muted">正在加载复盘…</p>
      ) : review ? (
        <p
          data-todo-review-summary={review.taskId}
          className="whitespace-pre-wrap text-xs leading-5 text-ink"
        >
          {review.summary}
        </p>
      ) : (
        <p className="text-xs text-muted">
          还没有复盘总结；完成任务前会自动弹窗收集。
        </p>
      )}
    </section>
  );
}

interface PendingReview {
  readonly taskId: string;
  readonly title: string;
  readonly resolve: (summary: string | null) => void;
}

/**
 * Client half of the dual-end seam: mounted into `todo.transition.guard`, it
 * registers an interceptor that opens a modal whenever a task is about to be
 * completed and no review summary has been provided yet.
 */
export function TodoReviewGuard({
  registerTransitionInterceptor,
}: TodoReviewGuardSlotProps) {
  const [pending, setPending] = useState<PendingReview | null>(null);
  const [summary, setSummary] = useState("");
  const [error, setError] = useState("");
  const pendingRef = useRef<PendingReview | null>(null);

  useEffect(() => {
    if (typeof registerTransitionInterceptor !== "function") return;

    return registerTransitionInterceptor((input: TodoReviewTransitionInput) => {
      const { task, nextState, meta } = input;
      if (nextState !== "done") return undefined;
      if (summaryFromMeta(meta) !== null) return undefined;

      return new Promise<string | void>((resolve) => {
        const request: PendingReview = {
          taskId: task.id,
          title: task.title?.trim() || "该任务",
          resolve: (collected) => {
            if (collected === null) {
              resolve("已取消复盘，任务未完成");
              return;
            }
            meta.review = { summary: collected };
            resolve();
          },
        };
        pendingRef.current = request;
        setSummary("");
        setError("");
        setPending(request);
      });
    });
  }, [registerTransitionInterceptor]);

  const settle = (value: string | null) => {
    const request = pendingRef.current;
    pendingRef.current = null;
    setPending(null);
    setError("");
    setSummary("");
    request?.resolve(value);
  };

  const handleSubmit = () => {
    const text = summary.trim();
    if (!text) {
      setError("请填写复盘总结后再完成任务");
      return;
    }
    if (text.length > MAX_SUMMARY_LENGTH) {
      setError(`复盘总结最多 ${MAX_SUMMARY_LENGTH} 个字符`);
      return;
    }
    settle(text);
  };

  if (!pending) return null;

  return (
    <div
      data-todo-review-dialog="true"
      role="dialog"
      aria-modal="true"
      aria-label="完成任务复盘"
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4"
    >
      <div className="w-full max-w-md rounded-lg border border-line bg-surface p-5 shadow-xl">
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <h2 className="flex items-center gap-1.5 text-base font-semibold text-ink">
              <CheckCheck className="size-4 text-accent" aria-hidden="true" />
              <span>完成任务复盘</span>
            </h2>
            <p
              data-todo-review-task={pending.taskId}
              className="mt-1 truncate text-xs text-muted"
            >
              任务：{pending.title}
            </p>
          </div>
          <button
            type="button"
            aria-label="取消复盘"
            onClick={() => settle(null)}
            className="inline-flex size-9 shrink-0 items-center justify-center rounded-md text-muted transition-colors hover:bg-canvas hover:text-ink"
          >
            <X className="size-4" aria-hidden="true" />
          </button>
        </div>

        <label
          htmlFor="todo-review-summary"
          className="mt-4 block text-xs font-medium text-muted"
        >
          复盘总结
        </label>
        <textarea
          id="todo-review-summary"
          data-todo-review-input="true"
          rows={5}
          value={summary}
          autoFocus
          onChange={(event) => setSummary(event.target.value)}
          placeholder="写下本次任务的关键结论、遗留问题与后续动作"
          className="mt-1.5 w-full resize-none rounded-md border border-line bg-surface px-3 py-2 text-sm text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
        />
        <p className="mt-1 text-[11px] tabular-nums text-muted">
          {summary.trim().length}/{MAX_SUMMARY_LENGTH}
        </p>

        {error && (
          <p
            role="alert"
            data-todo-review-error="true"
            className="mt-1 text-xs text-danger"
          >
            {error}
          </p>
        )}

        <div className="mt-4 flex items-center justify-end gap-2">
          <button
            type="button"
            data-todo-review-cancel="true"
            onClick={() => settle(null)}
            className="inline-flex min-h-9 items-center justify-center rounded-md border border-line bg-surface px-3 text-sm font-medium text-ink transition-colors hover:bg-canvas"
          >
            取消
          </button>
          <button
            type="button"
            data-todo-review-submit="true"
            onClick={handleSubmit}
            className="inline-flex min-h-9 items-center justify-center rounded-md bg-accent px-3 text-sm font-medium text-surface transition-colors hover:bg-accent/90"
          >
            确认完成
          </button>
        </div>
      </div>
    </div>
  );
}

type SlotEntry = {
  readonly name: string;
  readonly component: ComponentType<never>;
  readonly order: number;
};

interface SlotServiceLike {
  readonly register?: (...args: unknown[]) => unknown;
}

function describeMembers(value: object): string {
  const members = new Set<string>();
  let current: object | null = value;
  while (current && current !== Object.prototype) {
    for (const key of Object.getOwnPropertyNames(current)) members.add(key);
    current = Object.getPrototypeOf(current) as object | null;
  }
  return Array.from(members).sort().join(", ");
}

/** Mounts a component into a slot published through the client `slot` service. */
function mountInSlot(ctx: Context, entry: SlotEntry): void {
  const service = (ctx as unknown as { readonly slot?: SlotServiceLike }).slot;
  if (!service || typeof service.register !== "function") {
    throw new Error(
      `[todo-review] cannot mount slot "${entry.name}": slot service members = ${
        service ? describeMembers(service) : "missing"
      }`,
    );
  }

  const { name, component, order } = entry;
  const register = service.register.bind(service) as (
    ...args: unknown[]
  ) => unknown;
  const attempts: ReadonlyArray<() => unknown> = [
    () => register({ name, component, order }),
    () => register(name, { component, order }),
    () => register(name, component),
  ];

  let lastError: unknown = null;
  for (const attempt of attempts) {
    try {
      attempt();
      return;
    } catch (error) {
      lastError = error;
    }
  }
  throw new Error(
    `[todo-review] failed to mount slot "${name}": ${errorMessage(lastError)}`,
  );
}

/** `slot` is a client service, so the plugin must declare the injection. */
export const inject = ["slot"];

export default function apply(ctx: Context): void {
  ctx.inject(["slot"], (scoped) => {
    mountInSlot(scoped as Context, {
      name: "todo.transition.guard",
      component: TodoReviewGuard,
      order: 0,
    });
    mountInSlot(scoped as Context, {
      name: "todo.item.badges",
      component: TodoReviewBadge,
      order: 20,
    });
    mountInSlot(scoped as Context, {
      name: "todo.item.detail",
      component: TodoReviewDetail,
      order: 20,
    });
  });
}
