import { useCallback, useEffect, useState, type ComponentType } from "react";
import type { Context } from "cordis";
import { CheckCheck, ListTodo } from "lucide-react";
import type {
  TodoCounterSlotProps,
  TodoCounterTask,
  TodoCounts,
} from "./contract.d.ts";

const COUNTS_URL = "/api/app/todo-counter/counts";
const EMPTY_COUNTS: TodoCounts = { open: 0, done: 0, total: 0 };

async function requestJson<T>(url: string): Promise<T> {
  const response = await fetch(url, {
    headers: { "content-type": "application/json" },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

function isTodoCounts(value: unknown): value is TodoCounts {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.open === "number" &&
    typeof candidate.done === "number" &&
    typeof candidate.total === "number"
  );
}

function countTasks(tasks: readonly TodoCounterTask[]): TodoCounts {
  let open = 0;
  let done = 0;
  for (const task of tasks) {
    if (task.state === "done") done += 1;
    else open += 1;
  }
  return { open, done, total: open + done };
}

/** Compact open/done summary mounted in the todo header status area. */
export function TodoHeaderCounter({ tasks }: TodoCounterSlotProps) {
  const [remoteCounts, setRemoteCounts] = useState<TodoCounts>(EMPTY_COUNTS);

  const loadCounts = useCallback(async () => {
    try {
      const data = await requestJson<{ counts?: unknown }>(COUNTS_URL);
      if (isTodoCounts(data.counts)) setRemoteCounts(data.counts);
    } catch {
      // Counting must never break the header; keep the last known snapshot.
    }
  }, []);

  useEffect(() => {
    if (tasks === undefined) void loadCounts();
  }, [tasks, loadCounts]);

  const counts = tasks === undefined ? remoteCounts : countTasks(tasks);
  const label = `未完成 ${counts.open} 项，已完成 ${counts.done} 项，共 ${counts.total} 项`;

  return (
    <span
      role="status"
      aria-live="polite"
      aria-label={label}
      title={label}
      data-todo-counter="true"
      data-todo-counter-open={counts.open}
      data-todo-counter-done={counts.done}
      data-todo-counter-total={counts.total}
      className="inline-flex items-center gap-2 rounded-full border border-line bg-surface px-2.5 py-1 text-[11px] font-medium text-muted"
    >
      <span className="inline-flex items-center gap-1">
        <ListTodo className="size-3.5 text-accent" aria-hidden="true" />
        <span className="tabular-nums text-ink">未完成 {counts.open}</span>
      </span>
      <span aria-hidden="true" className="h-3 w-px bg-line" />
      <span className="inline-flex items-center gap-1">
        <CheckCheck className="size-3.5 text-muted" aria-hidden="true" />
        <span className="tabular-nums text-ink">已完成 {counts.done}</span>
      </span>
    </span>
  );
}

interface SlotServiceLike {
  readonly register?: (...args: unknown[]) => unknown;
}

interface SlotEntry {
  readonly name: string;
  readonly component: ComponentType<TodoCounterSlotProps>;
  readonly order: number;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/** Mounts the counter into a slot published by todo-core. */
function mountInSlot(ctx: Context, entry: SlotEntry): void {
  const service = (ctx as unknown as { readonly slot?: SlotServiceLike }).slot;
  if (!service || typeof service.register !== "function") {
    throw new Error(
      `[todo-counter] cannot mount slot "${entry.name}": slot service is unavailable`,
    );
  }

  const register = service.register.bind(service) as (
    ...args: unknown[]
  ) => unknown;
  const { name, component, order } = entry;

  try {
    register({ name, component, order });
  } catch (error) {
    try {
      register(name, { component, order });
    } catch (fallbackError) {
      throw new Error(
        `[todo-counter] failed to mount slot "${name}": ${errorMessage(
          fallbackError,
        )} (first attempt: ${errorMessage(error)})`,
      );
    }
  }
}

/** `slot` is a client service, so the plugin must declare the injection. */
export const inject = ["slot"];

export default function apply(ctx: Context): void {
  ctx.inject(["slot"], (scoped) => {
    mountInSlot(scoped as Context, {
      name: "todo.header.actions",
      component: TodoHeaderCounter,
      order: 0,
    });
  });
}

