import type {} from "cordis";

/** Palette tokens accepted for a tag color. */
export type TagColor =
  | "slate"
  | "blue"
  | "green"
  | "amber"
  | "rose"
  | "violet";

/**
 * A user owned label that can be attached to any number of tasks.
 *
 * `name` is returned exactly as stored: tags created since the normalization
 * change are lowercase, while tags written by older versions keep their
 * original casing and remain readable as-is.
 */
export interface Tag {
  readonly id: string;
  readonly name: string;
  readonly color: TagColor;
  readonly createdAt: string;
}

export interface CreateTagInput {
  /**
   * Raw user input. New tags are trimmed, whitespace-collapsed and lowercased
   * before they are stored.
   */
  readonly name: string;
  readonly color?: TagColor;
}

/**
 * Tag catalog plus task associations. Task ids are treated as opaque keys, so
 * this plugin never reaches into todo-core internals; the UI is projected into
 * the `todo.item.badges` / `todo.item.detail` slots published by todo-core.
 */
export interface TagService {
  list(): Tag[];
  get(id: string): Tag | null;
  /**
   * Create a tag from raw input.
   *
   * The name is normalized to lowercase and deduplicated case-insensitively:
   * saving "URGENT" after "urgent" (or after a legacy "Urgent") returns the
   * existing tag instead of inserting a duplicate. Existing rows are returned
   * untouched, so historical names stay readable with their original casing.
   */
  create(input: string | CreateTagInput): Tag;
  delete(id: string): boolean;
  listForTask(taskId: string): Tag[];
  attach(taskId: string, tagId: string): Tag[];
  detach(taskId: string, tagId: string): Tag[];
  setForTask(taskId: string, tagIds: readonly string[]): Tag[];
}

export interface TagsChangedPayload {
  /** `null` when the change originated from the tag catalog itself. */
  readonly taskId: string | null;
  readonly tagIds: readonly string[];
}

declare module "cordis" {
  interface Context {
    tags: TagService;
  }
  interface Events {
    "tags:changed"(payload: TagsChangedPayload): void;
  }
}

/** Minimal shape of the task object handed to `todo.item.*` slot components. */
export interface TagSlotTask {
  readonly id: string;
  readonly title?: string;
}

export interface TagSlotProps {
  readonly task: TagSlotTask;
}

