          <button
            type="button"
            data-todo-review-cancel="true"
            onClick={() => settle(null)}
            className="inline-flex min-h-9 items-center justify-center rounded-md border border-line bg-surface px-3 text-sm font-medium text-ink transition-colors hover:bg-canvas"
          >
            取消
          </button>
          <button
            type="button"
            data-todo-review-submit="true"
            onClick={handleSubmit}
            className="inline-flex min-h-9 items-center justify-center rounded-md bg-accent px-3 text-sm font-medium text-surface transition-colors hover:bg-accent/90"
          >
            确认完成
          </button>
        </div>
      </div>
    </div>
  );
}

type SlotEntry = {
  readonly name: string;
  readonly component: ComponentType<never>;
  readonly order: number;
};

interface SlotServiceLike {
  readonly register?: (...args: unknown[]) => unknown;
}

function describeMembers(value: object): string {
  const members = new Set<string>();
  let current: object | null = value;
  while (current && current !== Object.prototype) {
    for (const key of Object.getOwnPropertyNames(current)) members.add(key);
    current = Object.getPrototypeOf(current) as object | null;
  }
  return Array.from(members).sort().join(", ");
}

/** Mounts a component into a slot published through the client `slot` service. */
function mountInSlot(ctx: Context, entry: SlotEntry): void {
  const service = (ctx as unknown as { readonly slot?: SlotServiceLike }).slot;
  if (!service || typeof service.register !== "function") {
    throw new Error(
      `[todo-review] cannot mount slot "${entry.name}": slot service members = ${
        service ? describeMembers(service) : "missing"
      }`,
    );
  }

  const { name, component, order } = entry;
  const register = service.register.bind(service) as (
    ...args: unknown[]
  ) => unknown;
  const attempts: ReadonlyArray<() => unknown> = [
    () => register({ name, component, order }),
    () => register(name, { component, order }),
    () => register(name, component),
  ];

  let lastError: unknown = null;
  for (const attempt of attempts) {
    try {
      attempt();
      return;
    } catch (error) {
      lastError = error;
    }
  }
  throw new Error(
    `[todo-review] failed to mount slot "${name}": ${errorMessage(lastError)}`,
  );
}

/** `slot` is a client service, so the plugin must declare the injection. */
export const inject = ["slot"];

export default function apply(ctx: Context): void {
  ctx.inject(["slot"], (scoped) => {
    mountInSlot(scoped as Context, {
      name: "todo.transition.guard",
      component: TodoReviewGuard,
      order: 0,
    });
    mountInSlot(scoped as Context, {
      name: "todo.item.badges",
      component: TodoReviewBadge,
      order: 20,
    });
    mountInSlot(scoped as Context, {
      name: "todo.item.detail",
      component: TodoReviewDetail,
      order: 20,
    });
  });
