import { Service, type Context } from "cordis";
import type { ScopedDb } from "@host/server-sdk";
import type { Review, ReviewService } from "./contract.d.ts";

const MAX_SUMMARY_LENGTH = 2000;
const COLUMNS = "task_id, task_title, summary, created_at, updated_at";

interface Row { task_id: string; task_title: string; summary: string; created_at: string; updated_at: string; }
interface Payload { task?: { id?: unknown; title?: unknown }; nextState?: unknown; meta?: Record<string, unknown>; }
interface Bus { on(event: string, listener: (payload: unknown) => unknown): unknown; emit(event: string, payload: unknown): unknown; }

const toReview = (row: Row): Review => ({ taskId: row.task_id, taskTitle: row.task_title, summary: row.summary, createdAt: row.created_at, updatedAt: row.updated_at });

function readSummary(meta: Record<string, unknown> | undefined): string | null {
  if (!meta) return null;
  const raw = meta.review;
  if (typeof raw === "string") return raw.trim();
  if (raw && typeof raw === "object") {
    const value = (raw as { summary?: unknown }).summary;
    if (typeof value === "string") return value.trim();
  }
  return null;
}

export default class TodoReviewService extends Service implements ReviewService {
  private readonly db: ScopedDb;
  private readonly bus: Bus;

  constructor(ctx: Context) {
    super(ctx, "todoReview");
    this.db = ctx.db;
    this.bus = ctx as unknown as Bus;
    this.db.exec(`CREATE TABLE IF NOT EXISTS plg_todo_review__reviews (
      task_id TEXT PRIMARY KEY, task_title TEXT NOT NULL DEFAULT '',
      summary TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
    )`);
    ctx.http.route("GET", "/reviews", () => ({ reviews: this.list() }));
    ctx.http.route("GET", "/reviews/:taskId", (req) => ({ review: this.get(req.params.taskId) }));
    this.bus.on("todo:before-transition", (payload) => this.guard(payload as Payload));
  }

  list(): Review[] {
    return this.db.prepare(`SELECT ${COLUMNS} FROM plg_todo_review__reviews ORDER BY updated_at DESC, task_id ASC`).all<Row>().map(toReview);
  }

  get(taskId: string): Review | null {
    const row = this.db.prepare(`SELECT ${COLUMNS} FROM plg_todo_review__reviews WHERE task_id = ?`).get<Row>(taskId);
    return row ? toReview(row) : null;
  }

  private guard(payload: Payload): string | void {
    if (!payload || payload.nextState !== "done") return;
    const taskId = payload.task?.id;
    if (typeof taskId !== "string" || taskId.length === 0) return;
    const summary = readSummary(payload.meta);
    if (summary === null) return "完成任务前必须填写复盘总结";
    if (summary.length === 0) return "复盘总结不能为空";
    if (summary.length > MAX_SUMMARY_LENGTH) return `复盘总结最多 ${MAX_SUMMARY_LENGTH} 个字符`;
    this.record(taskId, typeof payload.task?.title === "string" ? payload.task.title : "", summary);
  }

  private record(taskId: string, taskTitle: string, summary: string): void {
    const now = new Date().toISOString();
    const existing = this.get(taskId);
    const title = taskTitle || existing?.taskTitle || "";
    this.db.prepare(`INSERT INTO plg_todo_review__reviews (task_id, task_title, summary, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?)
      ON CONFLICT(task_id) DO UPDATE SET task_title = excluded.task_title, summary = excluded.summary, updated_at = excluded.updated_at`)
      .run(taskId, title, summary, existing?.createdAt ?? now, now);
    const review = this.get(taskId);
    if (review) this.bus.emit("review:recorded", review);
  }
}
